    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int m = (int) in.nval;
        in.nextToken();
        int n = (int) in.nval;
        long[] a = new long[m];
        for (int i = 0; i < m; i++) {
            in.nextToken();
            a[i] = (long) in.nval;
        }
        long[][] res = spiralFill(a, n);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) sb.append(res[i][j]).append(j + 1 < n ? " " : "\n");
